class MyDataset(Dataset):
    """
    When using the model, 
    data_X is a list of multiple string sequences, generated by read_EC_actual_Fasta(fasta_file) which returns sequences:list, ids:list
    data_Y is pseudo_labels = np.zeros((len(input_seqs))), or a data label by np.load()
    make sure len(data_X) == len(data_Y)
    """
    def __init__(self, data_X, data_Y, data_W0, inference=False): # 1578, shuffle=False,  data_W, data_Y_epi 1576+2 = 1578
        # data_L, data_entry, 
        self.data_X = data_X
        self.inference=inference
        if not inference:
            # self.data_L = torch.from_numpy(np.vectorize(len)(data_X))
            self.data_Y = data_Y  # data_Y = {'mut':data, 'epi':data}. If only one target, then the dict has one element
            self.data_W0 = data_W0
        self.check_init()
        
    def check_init(self):
        print(f"\n\nCheck Dataset construction")
        print(f"X.shape = {self.data_X.shape}")
        print(f"Y.size = {self.data_Y.size()}")
        print(self.data_Y[:3, :7])
        print(f"W0.size = {self.data_W0.size()}")
        print(self.inference)
        
    def __len__(self):
        return len(self.data_X)
    
    def __getitem__(self, idx):
        if torch.is_tensor(idx):
            idx = idx.tolist()
        sample = {}
        seq = " ".join(str(self.data_X[idx]))
        seq = re.sub(r"[UZOB]", "X", seq)
        # print(len(self.data_X[idx]), "vs", len(attention_mask))
        l = len(str(self.data_X[idx]))

        if not self.inference:
            # 'length': self.data_L[idx]
            return {'model_input':{'x': self.data_X[idx]}, 
                    'evaluation_input':{'weight0': self.data_W0[idx], 
                                        'y_true':{data_target:self.data_Y[idx] 
                                                  for data_target in self.data_target_list}}
            }
        else:
            return {'model_input':{'x':self.data_X[idx]}, 
                    'evaluation_input':{'weight0': self.data_W0[idx]}
            }
    
    
def compileDataLoader_noSampler(train_data, cv_data, test_data, bs, logger=None): # 
    train_data = DataLoader(train_data, batch_size=bs, shuffle=True, pin_memory=True)  # , sampler=sampler
    cv_data = DataLoader(cv_data, batch_size=bs, shuffle=True, pin_memory=True)  # , sampler=sampler
    test_data = DataLoader(test_data, batch_size=bs, shuffle=True, pin_memory=True)  # , sampler=sampler
    logger.record(f"DataLoaders constructed with batch size = {bs}")
    return train_data, cv_data, test_data


def import_data(folder, bs, data_target_list, logger):
    X_train = np.load(f"{folder}/X_train.npy", allow_pickle=True)#[:bs]
    X_valid = np.load(f"{folder}/X_valid.npy", allow_pickle=True)#[:bs]
    X_test = np.load(f"{folder}/X_test.npy", allow_pickle=True)#[:bs]
    
    ## Only one target: epi or mut
    Y_train = {}
    Y_valid = {}
    Y_test = {}
    for data_target in data_target_list:
        Y_train[data_target] = torch.load(f"{folder}/Dataset_{data_target}_norm_train.pt", map_location='cpu', weights_only=True)#[:bs, :]
        Y_valid[data_target] = torch.load(f"{folder}/Dataset_{data_target}_norm_valid.pt", map_location='cpu', weights_only=True)#[:bs, :]
        Y_test[data_target] = torch.load(f"{folder}/Dataset_{data_target}_norm_test.pt", map_location='cpu', weights_only=True)#[:bs, :]
    
    W_train = torch.load(f"{folder}/W0_train_50.pt", map_location='cpu', weights_only=True)#[:bs]
    W_valid = torch.load(f"{folder}/W0_valid_50.pt", map_location='cpu', weights_only=True)#[:bs]
    W_test = torch.load(f"{folder}/W0_test_50.pt", map_location='cpu', weights_only=True)#[:bs]

    ## Compile dataset
    print("Creating train data")
    # train_data = MyDataset(X_train, Y_train_mut, Y_train_epi, W_train)  # be careful W0_train
    train_data = MyDataset(X_train, Y_train, W_train)  # be careful W0_train , L_train, entry_train
    print("Creating validation data")
    cv_data = MyDataset(X_valid, Y_valid, W_valid)
    print("Creating test data")
    test_data = MyDataset(X_test, Y_test, W_test)
    del X_train, X_valid, X_test, \
    Y_train, Y_valid, Y_test, \
    W_train, W_valid, W_test
    
    # y, num_to_samples, logger,
    train_data, cv_data, test_data = compileDataLoader_noSampler(train_data, cv_data, test_data, bs, logger)  # 
    return train_data, cv_data, test_data
